// A CommonJS module whose exports object is one of its own functions.
// Each table below is declared and attached in one statement, so the
// module-scope binding and the member name the same array; the functions
// of the module, declared further down, read the tables by their bindings.
exports = module.exports = Gauge

var patterns = exports.patterns = []
var sources = exports.sources = []
var labels = exports.labels = []
var EXACT = 0
var LOOSE = 1

sources[EXACT] = '^\\d+\\.\\d+$'
sources[LOOSE] = '^v?\\d+\\.\\d+$'
for (var i = 0; i < sources.length; i++) {
  if (!patterns[i]) {
    patterns[i] = new RegExp(sources[i])
  }
}

function fillLabels () {
  labels[EXACT] = 'exact'
  labels[LOOSE] = 'loose'
}
fillLabels()

exports.parse = parse
function parse (text, options) {
  if (!options || typeof options !== 'object') {
    options = { loose: !!options }
  }
  if (typeof text !== 'string') {
    return null
  }
  var pattern = options.loose ? patterns[LOOSE] : patterns[EXACT]
  if (!pattern.test(text)) {
    return null
  }
  return new Gauge(text)
}

exports.check = check
function check (text, options) {
  var parsed = parse(text, options)
  return parsed ? parsed.raw : null
}

exports.label = label
function label (index) {
  return labels[index]
}

function Gauge (text) {
  if (!(this instanceof Gauge)) {
    return new Gauge(text)
  }
  this.raw = text
}
